from playwright.sync_api import sync_playwright
U='http://localhost:5173';res=[]
def ok(n,c):res.append((n,bool(c)))
with sync_playwright() as p:
    b=p.chromium.launch();ctx=b.new_context(accept_downloads=True,viewport={'width':1366,'height':900});pg=ctx.new_page()
    errs=[];pg.on('pageerror',lambda e:errs.append(str(e)))
    def login(l):
        pg.goto(U+'/login');pg.evaluate('localStorage.removeItem("sl_user")');pg.goto(U+'/login');pg.click('text='+l);pg.click('text=Sign in as '+l);pg.wait_for_timeout(400)
    def go(x):pg.goto(U+x);pg.wait_for_timeout(700)
    T=lambda:pg.inner_text('main')
    login('Student')
    go('/student/dry-run');pg.get_by_role('button',name='Forward').click();pg.get_by_role('button',name='Forward').click();ok('dry run steps (i appears)','i' in T() and 'Step 3 of 8' in T())
    pg.get_by_role('button',name='Reset').click();ok('dry run reset','Step 1 of 8' in T())
    go('/student/viva');pg.get_by_role('button',name='Generate practice questions').click();pg.get_by_role('button',name='Reveal answer').first.click();ok('viva reveal','O(n²) in the worst case' in T())
    go('/student/assessments');pg.get_by_role('button',name='Start examination').click();ok('exam timer','left' in T());pg.get_by_role('button',name='Submit examination').click();ok('exam submitted','Submitted' in T())
    go('/student/assistant');pg.get_by_role('button',name='Explain time complexity').click();pg.wait_for_timeout(1000);ok('assistant replies','O(n²)' in T())
    go('/student/learning');ok('learning page','Concept performance' in T())
    go('/student/history');pg.locator('input[type=checkbox]').nth(0).check();pg.locator('input[type=checkbox]').nth(1).check();ok('history compare','v3' in T() and T().count('v')>3)
    go('/student/notes');pg.set_input_files('input[type=file]','/tmp/n.png');pg.wait_for_timeout(300);ok('note uploaded','n.png' in T())
    go('/student/records')
    with pg.expect_download() as d:pg.get_by_role('button',name='Download PDF').click()
    ok('record pdf download',d.value.suggested_filename=='lab-record.pdf')
    login('Faculty')
    go('/faculty/monitoring');pg.get_by_text('Rahul Verma').first.click();ok('monitor drawer','Send help message' in pg.inner_text('body'))
    go('/faculty/submissions');pg.get_by_role('button',name='Mark reviewed').click();ok('similarity reviewed','Status: Reviewed' in T())
    go('/faculty/assessments');pg.fill('input[name=title]','E2E exam');pg.fill('input[name=when]','2026-12-05T10:00');pg.fill('input[placeholder="Programming question"]','Q one');pg.get_by_role('button',name='Add',exact=True).click();pg.get_by_role('button',name='Schedule assessment').click();pg.wait_for_timeout(300);ok('assessment scheduled','E2E exam' in T())
    go('/faculty/viva');pg.fill('input[name=m]','8');pg.get_by_role('button',name='Save viva').click();ok('viva saved','8/10' in T())
    go('/faculty/resources');pg.get_by_role('button',name='Assign').first.click();pg.wait_for_timeout(200);ok('resource allocated','Allocated' in T())
    go('/faculty/attendance');pg.get_by_role('button',name='Absent').first.click();ok('attendance toggles','present' in T().lower() or 'absent' in T().lower())
    go('/faculty/experiments')
    with pg.expect_download() as d2:pg.get_by_role('button',name='Export CSV').click()
    ok('csv export',d2.value.suggested_filename.endswith('.csv'))
    pg.locator('button[aria-label=Delete]').first.click();pg.locator('button.danger').click();pg.wait_for_timeout(200);ok('delete works','4 records' in T() or '3 records' in T())
    login('HOD');go('/hod/internal-marks');pg.locator('input[type=range]').first.fill('70');ok('weights invalid disables publish',pg.get_by_role('button',name='Publish').is_disabled())
    login('Super Admin');go('/superadmin/colleges');pg.get_by_role('button',name='Deactivate').first.click();ok('college deactivated','Inactive' in T())
    pg.goto(U+'/forgot');ok('forgot page','Reset password' in pg.inner_text('body'))
    login('Student');pg.get_by_role('button',name='Profile menu').click();pg.get_by_text('Sign out').last.click();pg.wait_for_timeout(300);ok('logout redirects','/login' in pg.url)
    ok('no page errors',not errs)
    for n,c in res:print(('PASS ' if c else 'FAIL ')+n)
    print('errors:',errs[:3]);b.close()
